{{-- Professor principal e auxiliares vigentes da turma, com foto, para as listas de turmas. --}}
<span class="teacher-chips">@if($group->mainTeacher)<span class="teacher-chip"><x-person-photo :person="$group->mainTeacher->person" /><span>{{ $group->mainTeacher->person->social_name ?: $group->mainTeacher->person->full_name }} <small>principal</small></span></span>@else<span class="teacher-chip"><small>Professor a definir</small></span>@endif @foreach($group->currentAssistants as $assistant)<span class="teacher-chip"><x-person-photo :person="$assistant->teacher->person" /><span>{{ $assistant->teacher->person->social_name ?: $assistant->teacher->person->full_name }} <small>auxiliar</small></span></span>@endforeach</span>
